import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s5-u12")
C = "B1"
# Lições de aprofundamento (10–24): expressões idiomáticas agrupadas por tema.

def X(id, nl, pt): return V(id, nl, pt, "expression")

L(10, "Trabalhar muito", "Zich een slag in de rondte werken.",
  ["Usar expressões sobre esforço e trabalho intenso"],
  vocab=[X("v-slag-in-de-rondte","zich een slag in de rondte werken","trabalhar que nem um doido"), X("v-hoofd-boven-water","het hoofd boven water houden","manter-se à tona"),
         X("v-laatste-loodjes","de laatste loodjes wegen het zwaarst","o fim é sempre o mais difícil"), X("v-alle-hens-aan-dek","alle hens aan dek","todos ao trabalho!")],
  ex=[("Deze week heb ik me een slag in de rondte gewerkt.","Esta semana trabalhei que nem um doido."),("Met twee banen houdt ze het hoofd boven water.","Com dois empregos ela mantém-se à tona."),("Nog één examen: de laatste loodjes wegen het zwaarst!","Só mais um exame: o fim é sempre o mais difícil!"),("De klant komt morgen: alle hens aan dek!","O cliente vem amanhã: todos ao trabalho!")],
  review=["v-werkdruk"],
  cefr=C, exs=[
    MA([("zich een slag in de rondte werken","trabalhar imenso"),("het hoofd boven water houden","manter-se à tona"),("de laatste loodjes wegen het zwaarst","o fim é o mais difícil"),("alle hens aan dek","todos ao trabalho")], "Esforço.", ["v-slag-in-de-rondte","v-hoofd-boven-water","v-laatste-loodjes","v-alle-hens-aan-dek"]),
    EX("De laatste loodjes wegen het zwaarst.", "Os últimos pesos pesam mais.", "Quando se diz?", ["*Quando se está quase no fim de uma tarefa difícil","No início de um projeto|Não.","Ao fazer compras|Literal."], "Encorajamento final.", ["v-laatste-loodjes"]),
    EX("alle hens aan dek", "todas as mãos no convés", "Origem e sentido?", ["*Náutico: todos têm de ajudar já","Uma festa num barco|Não.","Uma ordem para descansar|Não."], "Linguagem marítima.", ["v-alle-hens-aan-dek"]),
    TR("nl-pt","Met twee banen houdt ze het hoofd boven water.", ["Com dois empregos ela mantém-se à tona","Com dois empregos ela consegue sobreviver"], "Sobreviver financeiramente.", ["v-hoofd-boven-water"]),
    FB("Ik heb me deze week een ___ in de rondte gewerkt.", ["slag"], "Expressão fixa.", ["v-slag-in-de-rondte"], choices=["slag","rondje","dag"], tr="Esta semana trabalhei que nem um doido."),
    DL([("Collega","Nog twee dagen tot de deadline… ik ben zo moe.","Faltam dois dias para o prazo… estou tão cansado."),("Jij","","")], ["*Volhouden! De laatste loodjes wegen het zwaarst.","Alle hens aan dek, ga naar huis.|Contraditório.","Je hoofd is boven water.|Não encaixa."], "Encorajar.", ["v-laatste-loodjes"]),
    MC("«Het hoofd boven water houden» refere-se muitas vezes a…", ["*dificuldades financeiras ou de trabalho","nadar|Literal.","lavar o cabelo|Não."], "Sentido figurado.", ["v-hoofd-boven-water"]),
    LI("Morgen komt de inspectie, dus alle hens aan dek!", ["Morgen komt de inspectie, dus alle hens aan dek","Morgen komt de inspectie dus alle hens aan dek"], "Amanhã vem a inspeção, por isso todos ao trabalho!", "Uso.", ["v-alle-hens-aan-dek"]),
    WO("Mantenho-me à tona.", ["Ik","houd","het","hoofd","boven","water"], "Expressão.", ["v-hoofd-boven-water"]),
  ], diff=3, mins=6)

